"""Generate optional, explicitly conditional hydrodynamic cone controls.

The verified baseline solvers are unchanged. These copies add measured cone
directions/speeds/times with assumed duration and density/thermal factors.
"""
from pathlib import Path
import hashlib, json, subprocess

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'solver/cme_cpu'
CONE_CODE=r'''
struct ConeBoundary{
 // start, end, inertial longitude, latitude, halfwidth, speed, n factor, T factor
 std::vector<std::array<double,8>> values;
 explicit ConeBoundary(const Config&c){
  auto file=c.s("cme_boundary_csv");if(file.empty())return;Csv table(file);
  std::array<int,8> columns;const char*names[]={"start_day","end_day","lon_rad","lat_rad","halfwidth_rad","speed_kms","density_factor","temperature_factor"};
  for(int d=0;d<8;++d)columns[d]=table.col(names[d]);
  for(const auto&row:table.rows){std::array<double,8> z;for(int d=0;d<8;++d)z[d]=row[columns[d]];
   if(!(z[1]>z[0]&&z[4]>0&&z[4]<PI/2&&z[5]>0&&z[6]>0&&z[7]>0))throw std::runtime_error("Invalid cone input");values.push_back(z);}
 }
 static double ramp(double x){x=std::clamp(x,0.,1.);double s=std::sin(.5*PI*x);return s*s;}
 void apply(double day,double lon,double lat,std::array<double,6>&b)const{
  double best=0;const std::array<double,8>*selected=nullptr;
  for(const auto&z:values){
   if(day<=z[0]||day>=z[1])continue;
   double cosine=std::sin(lat)*std::sin(z[3])+std::cos(lat)*std::cos(z[3])*std::cos(lon-z[2]);
   double angle=std::acos(std::clamp(cosine,-1.,1.));if(angle>=z[4])continue;
   double phase=(day-z[0])/(z[1]-z[0]);
   double temporal=ramp(std::min(phase,1-phase)/.1);
   double angular=ramp((1-angle/z[4])/.1),w=temporal*angular;
   // Distinct ejecta cannot simply multiply density at their overlapping
   // inflow pixels. Use the strongest envelope; later input wins equal w.
   if(w>=best){best=w;selected=&z;}
  }
  if(selected){const auto&z=*selected;b[0]+=(z[5]-b[0])*best;b[1]*=1+(z[6]-1)*best;b[3]*=1+(z[7]-1)*best;}
 }
};
'''

def extend(text):
    text=text.replace('struct Solver{',CONE_CODE+'\nstruct Solver{',1)
    needle='const Config&c;Boundary boundary;'
    assert text.count(needle)==1
    text=text.replace(needle,needle+'ConeBoundary cones;')
    needle='Solver(const Config&cfg):c(cfg),boundary(c){'
    assert text.count(needle)==1
    text=text.replace(needle,'Solver(const Config&cfg):c(cfg),boundary(c),cones(c){')
    needle='auto b=boundary.sample(time-lag,ph,PI/2-th);'
    assert text.count(needle)==1
    return text.replace(needle,needle+'cones.apply(time-lag,ph,PI/2-th,b);')

def main():
    OUT.mkdir(exist_ok=True);records=[]
    for suffix in ['', '_split']:
        source=ROOT/f'solver/induction_cpu/mhd_solver_inductive{suffix}.cpp'
        target=OUT/f'mhd_solver_cme{suffix}.cpp';target.write_text(extend(source.read_text()))
        executable=target.with_suffix('')
        command=['g++','-O3','-std=c++17','-fopenmp',str(target),'-o',str(executable)]
        subprocess.run(command,check=True)
        records.append(dict(base_source=str(source.relative_to(ROOT)),base_sha256=hashlib.sha256(source.read_bytes()).hexdigest(),
            source=str(target.relative_to(ROOT)),source_sha256=hashlib.sha256(target.read_bytes()).hexdigest(),
            executable_sha256=hashlib.sha256(executable.read_bytes()).hexdigest(),command=command))
    (OUT/'provenance.json').write_text(json.dumps(records,indent=2)+'\n')
    print('Built separate conditional CME CPU controls.')

if __name__=='__main__':main()
